import{z as C,x as s,o as t,c as n,q as l,j as o,D as r,d as e,s as B,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"掩模工艺修正 MPC","description":"","frontmatter":{"title":"掩模工艺修正 MPC","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mpc.md","filePath":"litho/mpc.md","lastUpdated":1791413859000}'),p={name:"litho/mpc.md"};function P(D,E,d,m,M,c){const A=s("Mermaid");return t(),n("div",null,[E[2]||(E[2]=l('<h1 id="掩模工艺修正-mpc" tabindex="-1">掩模工艺修正 MPC <a class="header-anchor" href="#掩模工艺修正-mpc" aria-label="Permalink to &quot;掩模工艺修正 MPC&quot;">​</a></h1><div class="epigraph"><p>OPC 修的是晶圆空中像；MPC 修的是版上从胶到吸收体的偏置——两套模型，一张掩模。</p><footer>—— 对照 mask process correction 与 e-beam / 掩模刻蚀偏置的产线通称</footer></div><p><a href="/litho/fracturing">上一课</a>把多边形收成可写的炮。缺口是写出、显影、刻铬/刻吸收体之后，版上 CD 仍不等于数据边：掩模刻蚀有负载，侧壁有倾角，电子雾化有残差。本课钉 MPC（mask process correction）。曲线数据量，留给<a href="/litho/curvilinear-data-volume">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/ebeam-mask-pec">PEC</a> 调的是写剂量，让胶上有效能量更均匀。胶边到金属边还有刻蚀偏置、微观负载和清洗损失。若把这些全塞进 PEC 核，换一套掩模干法配方时剂量模型一起坏。MPC 的对象是<strong>掩模工艺</strong>的几何或剂量补偿：让最终吸收体 CD 贴近 MDP 目标，而不是贴近胶边。</p><p>缺口是与晶圆 <a href="/litho/etch-in-opc">刻蚀进 OPC</a> 同构、但层不同。把 MPC 叫做「版厂 OPC」，会与客户 OPC 抢名：客户 OPC 假定掩模已经是目标尺寸；MPC 负责让这个假定大致成立。</p><p><span class="marginnote">直觉类比：PEC 像打印前调各处墨量，让纸上显出的笔画深浅均匀；MPC 像把字帖笔画预先描粗描细，抵消油墨洇开的方向——一个调「剂量」，一个调「形状」，目标都是让成品贴近原稿，只是发生在掩模厂、调的是版。</span></p><h3 id="几何-mpc-与剂量-mpc" tabindex="-1">几何 MPC 与剂量 MPC <a class="header-anchor" href="#几何-mpc-与剂量-mpc" aria-label="Permalink to &quot;几何 MPC 与剂量 MPC&quot;">​</a></h3><p>短程偏置可以用扩缩多边形（几何 MPC）；中远程负载可以用剂量微调或第二层密度图。过用几何会制造新 jog、与 MRC 打架；过用剂量会与 PEC 双计数。工程上按空间频率拆：纳米级边移给几何或短程剂量，微米级负载给密度核。</p><p><span class="marginnote">EUV 厚吸收体与高 Z 层的刻蚀偏置不同于二元铬。DUV 铬的 MPC 表不能贴到 Ta 基吸收体上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>校准：密集/孤立、通过节距、二维拐角的掩模 CD-SEM 或 AFM，ADI（掩模胶）与 AEI（吸收体）成对。模型进 MDP，在 fracturing 之前或之后应用——之后应用要能改炮尺寸或剂量。签核看的是 AEI 对目标，不是胶边。</p><p><span class="marginnote">术语翻译：ADI（显影后检查）与 AEI（刻蚀后检查）是版厂对同一位置在两道工序后的成对测量。两套 CD 一相减，就得到刻蚀偏置有多大——这张「工艺前后差表」就是 MPC 核的数据来源。</span></p>',13)),(t(),o(i,null,{default:r(()=>[B(A,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20BIAS%5B%22%E7%89%88%E4%B8%8A%E5%81%8F%E7%BD%AE%22%5D%20--%3E%20F%7B%22%E5%81%8F%E7%BD%AE%E7%9A%84%E7%A9%BA%E9%97%B4%E5%B0%BA%E5%BA%A6%3F%22%7D%0A%20%20F%20--%20%22%E7%BA%B3%E7%B1%B3%E7%BA%A7%20%E8%BE%B9%E9%99%84%E8%BF%91%22%20--%3E%20GEO%5B%22%E5%87%A0%E4%BD%95%20MPC%20%E6%89%A9%E7%BC%A9%E5%A4%9A%E8%BE%B9%E5%BD%A2%22%5D%0A%20%20F%20--%20%22%E7%9F%AD%E7%A8%8B%E4%B8%94%E5%AF%B9%E7%A7%B0%22%20--%3E%20DOSE%5B%22%E7%9F%AD%E7%A8%8B%E5%89%82%E9%87%8F%E5%BE%AE%E8%B0%83%22%5D%0A%20%20F%20--%20%22%E5%BE%AE%E7%B1%B3%E7%BA%A7%20%E8%B4%9F%E8%BD%BD%E5%9E%8B%22%20--%3E%20DENS%5B%22%E7%AC%AC%E4%BA%8C%E5%B1%82%E5%AF%86%E5%BA%A6%E5%9B%BE%22%5D%0A%20%20GEO%20--%3E%20COMB%5B%22%E5%90%88%E6%88%90%E4%BF%AE%E6%AD%A3%E5%90%8E%E6%95%B0%E6%8D%AE%22%5D%0A%20%20DOSE%20--%3E%20COMB%0A%20%20DENS%20--%3E%20COMB%0A%20%20COMB%20--%3E%20CHKE%7B%22%E4%B8%8E%20PEC%20%E5%8F%8C%E8%AE%A1%E6%95%B0%3F%20%E4%B8%8E%20MRC%20%E6%89%93%E6%9E%B6%3F%22%7D%0A%20%20CHKE%20--%20%22%E6%98%AF%22%20--%3E%20RED%5B%22%E9%80%80%E4%B8%80%E6%A1%A3%20%E9%87%8D%E6%8B%86%E9%A2%91%E7%8E%87%22%5D%0A%20%20CHKE%20--%20%22%E5%90%A6%22%20--%3E%20OUT%5B%22%E8%BF%9B%E5%86%99%E5%85%A5%22%5D%0A"})]),fallback:r(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[e("与 MEF 的衔接：晶圆看到的是 MPC 之后的残差乘 MEF。MPC 做过头会出现过校正振荡，密区过瘦，同样进 "),a("a",{href:"/litho/mask-cdu"},"mask CDU"),e("。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"掩模干法刻蚀的横向偏置随开口率变：密区聚合物多、过刻少，孤立线更瘦（或按化学相反）。这与晶圆 RIE 负载同类，尺度在掩模纳米到微米。MPC 核是这张负荷图的逆。侧壁倾角改变有效透射/反射边缘，进入掩模 3D；二维 MPC 若只修顶 CD，AIMS 仍会报打印差——那是后课鉴定的对象，本课先承认偏置有三维残差。",-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"常见误区：以为 MPC 修得越狠越好。过校正会出现振荡——密区反而过瘦；几何补偿若不与 PEC 剂量补偿按空间频率拆开，还会把同一偏置补两遍，掩模 CDU 不降反升。MPC 的功夫在「拆」，不在「补」。")],-1)),(t(),o(i,null,{default:r(()=>[B(A,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20TGT%5B%22MDP%20%E7%9B%AE%E6%A0%87%E8%BE%B9%22%5D%20--%3E%20PEC%5B%22PEC%3A%20%E8%83%B6%E5%89%82%E9%87%8F%22%5D%0A%20%20PEC%20--%3E%20ETCH%5B%22%E6%8E%A9%E6%A8%A1%E5%88%BB%E8%9A%80%E8%B4%9F%E8%BD%BD%22%5D%0A%20%20ETCH%20--%3E%20MPC%5B%22MPC%20%E5%87%A0%E4%BD%95%20%2F%20%E5%89%82%E9%87%8F%22%5D%0A%20%20MPC%20--%3E%20AEI%5B%22%E5%90%B8%E6%94%B6%E4%BD%93%20CD%22%5D%0A%20%20AEI%20--%3E%20WAFER%5B%22%E6%99%B6%E5%9C%86%20OPC%20%E5%81%87%E5%AE%9A%E7%9A%84%E6%8E%A9%E6%A8%A1%22%5D%0A"})]),fallback:r(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>MPC 不消除空白缺陷，不替代 pellicle。它只把掩模工艺的系统偏置收进数据。换胶、换刻蚀腔、换吸收体等于新 MPC。客户 OPC 版本必须与「MPC 后的掩模」绑定，否则窗口数字是另一张版。</p><p>后课默认：曼哈顿路径上工艺偏置有人修；曲线层的数据量会先问文件与栅格是否还撑得住这条链。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MPC 补偿掩模显影/刻蚀偏置；PEC 补偿电子剂量；OPC 补偿晶圆成像。</li><li>短程几何与长程密度核要拆开，避免与 PEC 双计数。</li><li>签核在吸收体 CD；残差经 MEF 进晶圆。</li><li>出处：mask process correction 产线通称；掩模刻蚀负载的公开讨论。</li></ul>',5))])}const f=C(p,[["render",P]]);export{u as __pageData,f as default};
